// Getting default attributes for entity type
EntityType<Zombie> zombieType = EntityType.ZOMBIE;

Optional<AttributeSupplier> attributes = DefaultAttributes.get(zombieType);
attributes.ifPresent(attrs -> {
    // Apply to custom mob
    mob.getAttribute(Attributes.MAX_HEALTH)
        .setBaseValue(attrs.getValue(Attributes.MAX_HEALTH));
});

// Custom attribute instance
AttributeInstance speed = mob.getAttribute(Attributes.MOVEMENT_SPEED);
speed.setBaseValue(0.3);
